#!/usr/bin/env node
// Turn public/rpd/item_registry.json into the C table the renderer compiles.
// The registry is generated by tools/build_item_registry.py; this step only
// resolves title ids to table indices so the native code never parses JSON.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const registry = JSON.parse(readFileSync(join(root, "public", "rpd", "item_registry.json"), "utf8"));
const items = registry.items;
const indexById = new Map(items.map((item, index) => [item.id, index]));
const ACTIONS = ["none", "take", "unlock", "open", "solve", "read", "use", "inspect"];

function escape(text) {
  return String(text).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function indices(ids) {
  return ids.map((id) => indexById.get(id)).filter((index) => index !== undefined);
}

function array(values) {
  const body = values.length ? values.join(", ") : "0";
  return `{ ${body} }`;
}

const limits = { requires: 8, requires_open: 8, contents: 4, opens: 12, external_requires: 2 };
for (const item of items) {
  for (const key of Object.keys(limits)) {
    const count = indices(item[key].length ? item[key] : []).length;
    if (count > limits[key]) throw new Error(`${item.title}: ${key} ${count} exceeds native limit ${limits[key]}`);
  }
  if ((item.hint ?? []).length > 2) throw new Error(`${item.title}: hint exceeds native limit 2`);
  if ((item.external_grants ?? []).length > 2) throw new Error(`${item.title}: external_grants exceeds native limit 2`);
}
const maxRequires = Math.max(...items.map((item) => indices(item.requires).length));
const maxOpen = Math.max(...items.map((item) => indices(item.requires_open).length));
const maxContents = Math.max(...items.map((item) => indices(item.contents).length));
const maxOpens = Math.max(...items.map((item) => indices(item.opens).length));
const maxExternal = Math.max(...items.map((item) => item.external_requires.length));

const rows = items.map((item) => {
  const requires = indices(item.requires);
  const requiresOpen = indices(item.requires_open);
  const contents = indices(item.contents);
  const opens = indices(item.opens);
  const hints = indices(item.hint ?? []);
  const hidden = item.hidden_by === null ? -1 : indexById.get(item.hidden_by) ?? -1;
  const flags = (item.on_floor ? 1 : 0) | (item.on_door ? 2 : 0) | (item.on_stair ? 4 : 0) | (item.nearest_nav > 2.0 ? 8 : 0);
  const external = item.external_requires.map((entry) => entry.id);
  const externalGrants = item.external_grants ?? [];
  const transition = (item.links ?? []).find(
    (link) => link.section === "transition to" || link.section === "transition to / from",
  );
  const transitionTarget = transition ? transition.id : 0;
  return `    { ${item.id}, "${escape(item.title)}", "${escape(item.category)}", "${escape(item.icon)}", ${item.x.toFixed(4)}f, ${item.y.toFixed(4)}f, ${item.z.toFixed(4)}f, ${item.floor}, ${ACTIONS.indexOf(item.action)}, ${item.placement === "fixture" ? 1 : 0}, ${flags}, ${item.blocks ? 1 : 0}, ${hidden}, ${array(requires)}, ${requires.length}, ${array(requiresOpen)}, ${requiresOpen.length}, ${array(contents)}, ${contents.length}, ${array(opens)}, ${opens.length}, ${array(external)}, ${external.length}, ${item.code ? `"${escape(item.code)}"` : "NULL"}, ${array(hints)}, ${hints.length}, ${array(externalGrants)}, ${externalGrants.length}, ${transitionTarget} },`;
});

const header = `// Generated by tools/gen_item_registry.mjs from public/rpd/item_registry.json.
// Do not edit; change the registry tool and rerun it.
#pragma once

#define RPD_ITEM_COUNT ${items.length}
#define RPD_ITEM_BLOCK_RADIUS ${Number(registry.block_radius).toFixed(2)}f

static const rpd_item_def_t RPD_ITEM_DEFS[RPD_ITEM_COUNT] = {
${rows.join("\n")}
};
`;

mkdirSync(join(root, "native", "gen"), { recursive: true });
writeFileSync(join(root, "native", "gen", "rpd_item_registry.h"), header);
console.log(`wrote native/gen/rpd_item_registry.h (${items.length} items, max requires ${maxRequires}, opens ${maxOpens}, external ${maxExternal})`);
